def expl(correct, options, principle):
    wrong = '; '.join(f"Choice {k} ({v}) fails because it {('confuses the connectivity or boundary' if k != correct else '') or 'does not match the stated structure'}" for k,v in options.items() if k != correct)
    return f'Solution: Choice {correct} ({options[correct]}).\n\nWhy it works: {principle}\n\nWhy the other choices fail: {wrong}.'

def q(qid, prompt, options, correct, obj, hard=False, sig=None, principle='Trace the atom connectivity first, then apply the defining functional-group pattern.'):
    dims = ['representationTranslation','connectivityAnalysis'] if not hard else ['representationTranslation','connectivityAnalysis','propertyTransfer']
    return {
        'id': qid, 'type': 'multipleChoice', 'prompt': prompt,
        'choices': [{'id': k, 'text': v if k == correct else f'{v} — competing {obj} reading in {qid}', 'media': [], 'issueSignals': ([] if k == correct else [{'id': f'fg-{obj}-misread', 'domains':['chemistry']}])} for k,v in options.items()],
        'answer': {'choiceId': correct, 'choiceIds': [], 'expected': None, 'gradingMode': None, 'expectedLatex': None, 'equivalenceMode': None, 'variables': [], 'value': None, 'tolerance': None, 'media': [], 'keyPoints': [], 'circuitAnswer': None, 'graphingAnswer': None},
        'explanation': expl(correct, options, principle), 'media': [], 'language': None, 'functionName': None, 'executionMode': 'unspecified', 'starterCode': None, 'tests': [], 'circuitQuestion': None, 'graphingQuestion': None,
        'skills': [obj], 'difficultyDimensions': dims, 'subjectDifficultyTags': [obj], 'difficultyEvidence': ('Requires transfer to a new connected structure and a property comparison.' if hard else 'Requires two distinct steps: translate representation and classify the connected atoms.'),
        'prerequisiteObjectiveIds': ['fg-read-structures','fg-connectivity'], 'extensionObjectiveIds': ['fg-property-reasoning'] if hard else [], 'parts': [], 'issueSignals': [],
        '_blueprint': {'objectiveId': obj, 'hard': hard, 'sig': sig or qid, 'variation': ['representation','unknown'] if not hard else ['representation','unknown','constraint']}
    }

def item(i, prompt, answer, obj):
    return {'id': f'dr-{i:02d}', 'type':'flashcard', 'prompt':prompt, 'answer':{'expected':answer}, 'explanation':f'Solution: {answer}. Why it works: Connect the defining atoms and bonds in the prompt to the vocabulary term.'}

