def blueprint_for(data):
    records=[]
    for qq in data.get('questions',[]):
        b=qq.pop('_blueprint',None)
        if not b: continue
        records.append({'id':f"{data['id']}-{qq['id']}-bp",'assessmentId':data['id'],'questionId':qq['id'],'objectiveId':b['objectiveId'],'sourceChunks':chunks[:3] if b['objectiveId'] != 'fg-property' else chunks[-3:],'reviewState':'approved','questionType':qq['type'],'givens':qq['prompt'],'unknown':'functional-group classification or qualitative property relation','representationRequirement':'Trace every explicitly shown bond and local neighborhood.','governingPrinciple':'Classify by the directly connected atoms and bond orders; then compare polar and nonpolar contributions when properties are asked.','methodSteps':['translate the representation','isolate the local connectivity','name the matching group','check competing boundaries and property assumptions'],'likelyMisconception':'confusing an oxygen or nitrogen atom label with the complete connected functional group','difficultyEvidence':qq['difficultyEvidence'],'answerVerificationMethod':'Independent connectivity redraw and group-boundary check; property items checked against donor/acceptor and hydrocarbon-size reasoning.','variationAxes':b['variation'],'reasoningSignature':b['sig'],'difficultyDimensions':qq['difficultyDimensions'],'prerequisiteObjectiveIds':qq['prerequisiteObjectiveIds'],'extensionObjectiveIds':qq['extensionObjectiveIds']})
    return {'schemaVersion':1,'id':data['id']+'-blueprints','categoryId':'chemistry','topicId':TOPIC,'assessmentId':data['id'],'packetId':PACKET,'blueprints':records}
for data in [practice,master]: (BLUE/(data['id']+'-blueprints.yaml')).write_text(yaml.safe_dump(blueprint_for(data),sort_keys=False,allow_unicode=True,width=120),encoding='utf-8')

